-- Gerado por scripts/generate-complete-grammar.mjs.

insert into public.grammar_topics (
  id, language, level, title, overview_pt_br, formation_pt_br,
  use_cases, common_mistakes, notes_pt_br, sort_order
) values
  ('en-grammar-complete-a1-01', 'en', 'A1', 'Pronomes sujeito e objeto', 'Use sujeito antes do verbo e objeto depois do verbo ou preposição. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use sujeito antes do verbo e objeto depois do verbo ou preposição. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use sujeito antes do verbo e objeto depois do verbo ou preposição.","examples":[{"target":"She calls me every day.","translation_pt_br":"Ela me liga todos os dias."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronomes sujeito e objeto.","examples":[{"target":"We work with them.","translation_pt_br":"Trabalhamos com eles."}]}]'::jsonb, '[{"incorrect":"Her calls I every day.","correct":"She calls me every day.","explanation_pt_br":"A forma incorreta ignora esta regra: Use sujeito antes do verbo e objeto depois do verbo ou preposição."},{"incorrect":"Us work with they.","correct":"We work with them.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronomes sujeito e objeto."}]'::jsonb, '["Pratique Pronomes sujeito e objeto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 200),
  ('en-grammar-complete-a1-02', 'en', 'A1', 'Possessivos e demonstrativos', 'Adjetivos possessivos vêm antes do nome; pronomes possessivos o substituem. This/these indicam proximidade. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Adjetivos possessivos vêm antes do nome; pronomes possessivos o substituem. This/these indicam proximidade. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Adjetivos possessivos vêm antes do nome; pronomes possessivos o substituem. This/these indicam proximidade.","examples":[{"target":"This is my book; that one is yours.","translation_pt_br":"Este é meu livro; aquele é seu."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Possessivos e demonstrativos.","examples":[{"target":"These shoes are hers.","translation_pt_br":"Estes sapatos são dela."}]}]'::jsonb, '[{"incorrect":"This is mine book.","correct":"This is my book; that one is yours.","explanation_pt_br":"A forma incorreta ignora esta regra: Adjetivos possessivos vêm antes do nome; pronomes possessivos o substituem. This/these indicam proximidade."},{"incorrect":"This shoes are her.","correct":"These shoes are hers.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Possessivos e demonstrativos."}]'::jsonb, '["Pratique Possessivos e demonstrativos em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 201),
  ('en-grammar-complete-a1-03', 'en', 'A1', 'Have, have got e posse', 'Have e have got expressam posse; perguntas usam do/does com have ou inversão com have got. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Have e have got expressam posse; perguntas usam do/does com have ou inversão com have got. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Have e have got expressam posse; perguntas usam do/does com have ou inversão com have got.","examples":[{"target":"I have a new phone.","translation_pt_br":"Tenho um telefone novo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Have, have got e posse.","examples":[{"target":"Has she got any brothers?","translation_pt_br":"Ela tem irmãos?"}]}]'::jsonb, '[{"incorrect":"I am have a new phone.","correct":"I have a new phone.","explanation_pt_br":"A forma incorreta ignora esta regra: Have e have got expressam posse; perguntas usam do/does com have ou inversão com have got."},{"incorrect":"Does she has got brothers?","correct":"Has she got any brothers?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Have, have got e posse."}]'::jsonb, '["Pratique Have, have got e posse em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 202),
  ('en-grammar-complete-a1-04', 'en', 'A1', 'Present simple: verbos frequentes', 'Use a forma base com I/you/we/they e acrescente -s/-es com he/she/it; do/does formam perguntas e negativas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use a forma base com I/you/we/they e acrescente -s/-es com he/she/it; do/does formam perguntas e negativas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use a forma base com I/you/we/they e acrescente -s/-es com he/she/it; do/does formam perguntas e negativas.","examples":[{"target":"He works and studies at night.","translation_pt_br":"Ele trabalha e estuda à noite."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Present simple: verbos frequentes.","examples":[{"target":"Do they live near here?","translation_pt_br":"Eles moram perto daqui?"}]}]'::jsonb, '[{"incorrect":"He work and study at night.","correct":"He works and studies at night.","explanation_pt_br":"A forma incorreta ignora esta regra: Use a forma base com I/you/we/they e acrescente -s/-es com he/she/it; do/does formam perguntas e negativas."},{"incorrect":"Does they lives near here?","correct":"Do they live near here?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Present simple: verbos frequentes."}]'::jsonb, '["Pratique Present simple: verbos frequentes em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 203),
  ('en-grammar-complete-a1-05', 'en', 'A1', 'Can, can''t e habilidades', 'Can + verbo base expressa habilidade, possibilidade ou pedido; não recebe -s nem usa to. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Can + verbo base expressa habilidade, possibilidade ou pedido; não recebe -s nem usa to. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Can + verbo base expressa habilidade, possibilidade ou pedido; não recebe -s nem usa to.","examples":[{"target":"She can speak Italian.","translation_pt_br":"Ela sabe falar italiano."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Can, can''t e habilidades.","examples":[{"target":"Can you help me?","translation_pt_br":"Você pode me ajudar?"}]}]'::jsonb, '[{"incorrect":"She cans to speak Italian.","correct":"She can speak Italian.","explanation_pt_br":"A forma incorreta ignora esta regra: Can + verbo base expressa habilidade, possibilidade ou pedido; não recebe -s nem usa to."},{"incorrect":"Do you can help me?","correct":"Can you help me?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Can, can''t e habilidades."}]'::jsonb, '["Pratique Can, can''t e habilidades em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 204),
  ('en-grammar-complete-a1-06', 'en', 'A1', 'Question words e perguntas básicas', 'Use what, where, when, who, why, which e how antes do auxiliar ou do verbo be. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use what, where, when, who, why, which e how antes do auxiliar ou do verbo be. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use what, where, when, who, why, which e how antes do auxiliar ou do verbo be.","examples":[{"target":"Where do you work?","translation_pt_br":"Onde você trabalha?"}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Question words e perguntas básicas.","examples":[{"target":"How old is your sister?","translation_pt_br":"Quantos anos tem sua irmã?"}]}]'::jsonb, '[{"incorrect":"Where you work?","correct":"Where do you work?","explanation_pt_br":"A forma incorreta ignora esta regra: Use what, where, when, who, why, which e how antes do auxiliar ou do verbo be."},{"incorrect":"How many years has your sister?","correct":"How old is your sister?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Question words e perguntas básicas."}]'::jsonb, '["Pratique Question words e perguntas básicas em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 205),
  ('en-grammar-complete-a2-01', 'en', 'A2', 'Present continuous e ações temporárias', 'Forme be + verbo-ing para ações em curso, situações temporárias e planos combinados. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Forme be + verbo-ing para ações em curso, situações temporárias e planos combinados. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Forme be + verbo-ing para ações em curso, situações temporárias e planos combinados.","examples":[{"target":"I''m working from home this week.","translation_pt_br":"Estou trabalhando de casa esta semana."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Present continuous e ações temporárias.","examples":[{"target":"We''re meeting Ana tomorrow.","translation_pt_br":"Vamos encontrar Ana amanhã."}]}]'::jsonb, '[{"incorrect":"I working from home this week.","correct":"I''m working from home this week.","explanation_pt_br":"A forma incorreta ignora esta regra: Forme be + verbo-ing para ações em curso, situações temporárias e planos combinados."},{"incorrect":"We meet Ana tomorrow now.","correct":"We''re meeting Ana tomorrow.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Present continuous e ações temporárias."}]'::jsonb, '["Pratique Present continuous e ações temporárias em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 206),
  ('en-grammar-complete-a2-02', 'en', 'A2', 'Past simple: verbos irregulares comuns', 'Use a forma irregular na afirmativa e did + forma base na negativa ou pergunta. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use a forma irregular na afirmativa e did + forma base na negativa ou pergunta. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use a forma irregular na afirmativa e did + forma base na negativa ou pergunta.","examples":[{"target":"She went home and made dinner.","translation_pt_br":"Ela foi para casa e preparou o jantar."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Past simple: verbos irregulares comuns.","examples":[{"target":"Did you see the message?","translation_pt_br":"Você viu a mensagem?"}]}]'::jsonb, '[{"incorrect":"She goed home and maked dinner.","correct":"She went home and made dinner.","explanation_pt_br":"A forma incorreta ignora esta regra: Use a forma irregular na afirmativa e did + forma base na negativa ou pergunta."},{"incorrect":"Did you saw the message?","correct":"Did you see the message?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Past simple: verbos irregulares comuns."}]'::jsonb, '["Pratique Past simple: verbos irregulares comuns em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 207),
  ('en-grammar-complete-a2-03', 'en', 'A2', 'Comparativos e superlativos', 'Use -er/-est em adjetivos curtos e more/most nos longos; comparativos normalmente usam than. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use -er/-est em adjetivos curtos e more/most nos longos; comparativos normalmente usam than. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use -er/-est em adjetivos curtos e more/most nos longos; comparativos normalmente usam than.","examples":[{"target":"This route is faster than the other one.","translation_pt_br":"Esta rota é mais rápida que a outra."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Comparativos e superlativos.","examples":[{"target":"It''s the most useful option.","translation_pt_br":"É a opção mais útil."}]}]'::jsonb, '[{"incorrect":"This route is more faster.","correct":"This route is faster than the other one.","explanation_pt_br":"A forma incorreta ignora esta regra: Use -er/-est em adjetivos curtos e more/most nos longos; comparativos normalmente usam than."},{"incorrect":"It''s the usefulest option.","correct":"It''s the most useful option.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Comparativos e superlativos."}]'::jsonb, '["Pratique Comparativos e superlativos em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 208),
  ('en-grammar-complete-a2-04', 'en', 'A2', 'Advérbios de frequência e modo', 'Always/usually/often vêm antes do verbo principal e depois de be; advérbios de modo geralmente vêm após o verbo ou objeto. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Always/usually/often vêm antes do verbo principal e depois de be; advérbios de modo geralmente vêm após o verbo ou objeto. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Always/usually/often vêm antes do verbo principal e depois de be; advérbios de modo geralmente vêm após o verbo ou objeto.","examples":[{"target":"She usually arrives early.","translation_pt_br":"Ela geralmente chega cedo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Advérbios de frequência e modo.","examples":[{"target":"He speaks English fluently.","translation_pt_br":"Ele fala inglês fluentemente."}]}]'::jsonb, '[{"incorrect":"She arrives usually early.","correct":"She usually arrives early.","explanation_pt_br":"A forma incorreta ignora esta regra: Always/usually/often vêm antes do verbo principal e depois de be; advérbios de modo geralmente vêm após o verbo ou objeto."},{"incorrect":"He speaks fluently English.","correct":"He speaks English fluently.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Advérbios de frequência e modo."}]'::jsonb, '["Pratique Advérbios de frequência e modo em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 209),
  ('en-grammar-complete-a2-05', 'en', 'A2', 'Should, must e have to', 'Should aconselha; must expressa obrigação forte do falante; have to indica obrigação externa; mustn''t proíbe. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Should aconselha; must expressa obrigação forte do falante; have to indica obrigação externa; mustn''t proíbe. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Should aconselha; must expressa obrigação forte do falante; have to indica obrigação externa; mustn''t proíbe.","examples":[{"target":"You should rest today.","translation_pt_br":"Você deveria descansar hoje."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Should, must e have to.","examples":[{"target":"Employees have to wear a badge.","translation_pt_br":"Funcionários precisam usar crachá."}]}]'::jsonb, '[{"incorrect":"You should to rest today.","correct":"You should rest today.","explanation_pt_br":"A forma incorreta ignora esta regra: Should aconselha; must expressa obrigação forte do falante; have to indica obrigação externa; mustn''t proíbe."},{"incorrect":"Employees have wear a badge.","correct":"Employees have to wear a badge.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Should, must e have to."}]'::jsonb, '["Pratique Should, must e have to em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 210),
  ('en-grammar-complete-b1-01', 'en', 'B1', 'Present perfect e experiências', 'Use have/has + particípio para experiência, resultado presente e período ainda aberto; evite tempo passado concluído. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use have/has + particípio para experiência, resultado presente e período ainda aberto; evite tempo passado concluído. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use have/has + particípio para experiência, resultado presente e período ainda aberto; evite tempo passado concluído.","examples":[{"target":"I''ve visited Rome twice.","translation_pt_br":"Visitei Roma duas vezes."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Present perfect e experiências.","examples":[{"target":"She has worked here since 2022.","translation_pt_br":"Ela trabalha aqui desde 2022."}]}]'::jsonb, '[{"incorrect":"I have visit Rome twice.","correct":"I''ve visited Rome twice.","explanation_pt_br":"A forma incorreta ignora esta regra: Use have/has + particípio para experiência, resultado presente e período ainda aberto; evite tempo passado concluído."},{"incorrect":"She works here since 2022.","correct":"She has worked here since 2022.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Present perfect e experiências."}]'::jsonb, '["Pratique Present perfect e experiências em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 211),
  ('en-grammar-complete-b1-02', 'en', 'B1', 'Relative clauses', 'Who refere-se a pessoas, which a coisas e that a ambos em restritivas; whose indica posse e where indica lugar. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Who refere-se a pessoas, which a coisas e that a ambos em restritivas; whose indica posse e where indica lugar. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Who refere-se a pessoas, which a coisas e that a ambos em restritivas; whose indica posse e where indica lugar.","examples":[{"target":"The colleague who helped me is new.","translation_pt_br":"O colega que me ajudou é novo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Relative clauses.","examples":[{"target":"This is the office where I work.","translation_pt_br":"Este é o escritório onde trabalho."}]}]'::jsonb, '[{"incorrect":"The colleague which helped me is new.","correct":"The colleague who helped me is new.","explanation_pt_br":"A forma incorreta ignora esta regra: Who refere-se a pessoas, which a coisas e that a ambos em restritivas; whose indica posse e where indica lugar."},{"incorrect":"This is the office who I work.","correct":"This is the office where I work.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Relative clauses."}]'::jsonb, '["Pratique Relative clauses em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 212),
  ('en-grammar-complete-b1-03', 'en', 'B1', 'Passive voice', 'Forme be no tempo necessário + particípio; use by apenas quando o agente for relevante. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Forme be no tempo necessário + particípio; use by apenas quando o agente for relevante. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Forme be no tempo necessário + particípio; use by apenas quando o agente for relevante.","examples":[{"target":"The report was sent yesterday.","translation_pt_br":"O relatório foi enviado ontem."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Passive voice.","examples":[{"target":"English is spoken worldwide.","translation_pt_br":"Inglês é falado no mundo todo."}]}]'::jsonb, '[{"incorrect":"The report sent yesterday.","correct":"The report was sent yesterday.","explanation_pt_br":"A forma incorreta ignora esta regra: Forme be no tempo necessário + particípio; use by apenas quando o agente for relevante."},{"incorrect":"English speaks worldwide.","correct":"English is spoken worldwide.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Passive voice."}]'::jsonb, '["Pratique Passive voice em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 213),
  ('en-grammar-complete-b1-04', 'en', 'B1', 'Reported speech', 'Ao relatar fala passada, ajuste pronomes, referências de tempo e normalmente recue o tempo verbal. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Ao relatar fala passada, ajuste pronomes, referências de tempo e normalmente recue o tempo verbal. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Ao relatar fala passada, ajuste pronomes, referências de tempo e normalmente recue o tempo verbal.","examples":[{"target":"She said that she was tired.","translation_pt_br":"Ela disse que estava cansada."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Reported speech.","examples":[{"target":"He asked me where I lived.","translation_pt_br":"Ele perguntou onde eu morava."}]}]'::jsonb, '[{"incorrect":"She said that I am tired.","correct":"She said that she was tired.","explanation_pt_br":"A forma incorreta ignora esta regra: Ao relatar fala passada, ajuste pronomes, referências de tempo e normalmente recue o tempo verbal."},{"incorrect":"He asked me where did I live.","correct":"He asked me where I lived.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Reported speech."}]'::jsonb, '["Pratique Reported speech em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 214),
  ('en-grammar-complete-a1-07', 'en', 'A1', 'Imperatives e let''s', 'Use verbo base para instruções, don''t + verbo para proibição e let''s + verbo para sugestões inclusivas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use verbo base para instruções, don''t + verbo para proibição e let''s + verbo para sugestões inclusivas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use verbo base para instruções, don''t + verbo para proibição e let''s + verbo para sugestões inclusivas.","examples":[{"target":"Open the window, please.","translation_pt_br":"Abra a janela, por favor."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Imperatives e let''s.","examples":[{"target":"Let''s take a short break.","translation_pt_br":"Vamos fazer uma pausa curta."}]}]'::jsonb, '[{"incorrect":"You open the window please.","correct":"Open the window, please.","explanation_pt_br":"A forma incorreta ignora esta regra: Use verbo base para instruções, don''t + verbo para proibição e let''s + verbo para sugestões inclusivas."},{"incorrect":"Let''s to take a short break.","correct":"Let''s take a short break.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Imperatives e let''s."}]'::jsonb, '["Pratique Imperatives e let''s em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 215),
  ('en-grammar-complete-b2-01', 'en', 'B2', 'Modal perfect', 'Use modal + have + particípio para deduzir, criticar ou imaginar alternativas sobre o passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use modal + have + particípio para deduzir, criticar ou imaginar alternativas sobre o passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use modal + have + particípio para deduzir, criticar ou imaginar alternativas sobre o passado.","examples":[{"target":"He must have forgotten the meeting.","translation_pt_br":"Ele deve ter esquecido a reunião."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Modal perfect.","examples":[{"target":"You should have told me earlier.","translation_pt_br":"Você deveria ter me contado antes."}]}]'::jsonb, '[{"incorrect":"He must has forgotten.","correct":"He must have forgotten the meeting.","explanation_pt_br":"A forma incorreta ignora esta regra: Use modal + have + particípio para deduzir, criticar ou imaginar alternativas sobre o passado."},{"incorrect":"You should told me earlier.","correct":"You should have told me earlier.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Modal perfect."}]'::jsonb, '["Pratique Modal perfect em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 216),
  ('en-grammar-complete-b2-02', 'en', 'B2', 'Mixed conditionals', 'Combine tempos quando a condição passada produz resultado presente ou uma condição atual explica resultado passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Combine tempos quando a condição passada produz resultado presente ou uma condição atual explica resultado passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Combine tempos quando a condição passada produz resultado presente ou uma condição atual explica resultado passado.","examples":[{"target":"If I had studied medicine, I would be a doctor now.","translation_pt_br":"Se tivesse estudado medicina, seria médico agora."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Mixed conditionals.","examples":[{"target":"If she were more organized, she wouldn''t have missed it.","translation_pt_br":"Se fosse mais organizada, não teria perdido."}]}]'::jsonb, '[{"incorrect":"If I would have studied, I was a doctor.","correct":"If I had studied medicine, I would be a doctor now.","explanation_pt_br":"A forma incorreta ignora esta regra: Combine tempos quando a condição passada produz resultado presente ou uma condição atual explica resultado passado."},{"incorrect":"If she was organized, she won''t missed it.","correct":"If she were more organized, she wouldn''t have missed it.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Mixed conditionals."}]'::jsonb, '["Pratique Mixed conditionals em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 217),
  ('en-grammar-complete-b2-03', 'en', 'B2', 'Inversion for emphasis', 'Depois de advérbios negativos iniciais, inverta auxiliar e sujeito para ênfase formal. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Depois de advérbios negativos iniciais, inverta auxiliar e sujeito para ênfase formal. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Depois de advérbios negativos iniciais, inverta auxiliar e sujeito para ênfase formal.","examples":[{"target":"Never have I seen such a result.","translation_pt_br":"Nunca vi um resultado assim."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Inversion for emphasis.","examples":[{"target":"Only then did we understand the risk.","translation_pt_br":"Só então entendemos o risco."}]}]'::jsonb, '[{"incorrect":"Never I have seen such a result.","correct":"Never have I seen such a result.","explanation_pt_br":"A forma incorreta ignora esta regra: Depois de advérbios negativos iniciais, inverta auxiliar e sujeito para ênfase formal."},{"incorrect":"Only then we understood the risk.","correct":"Only then did we understand the risk.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Inversion for emphasis."}]'::jsonb, '["Pratique Inversion for emphasis em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 218),
  ('en-grammar-complete-b2-04', 'en', 'B2', 'Participle clauses', 'Use particípio presente para ações simultâneas/causais e particípio passado para sentido passivo, mantendo o mesmo sujeito. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use particípio presente para ações simultâneas/causais e particípio passado para sentido passivo, mantendo o mesmo sujeito. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use particípio presente para ações simultâneas/causais e particípio passado para sentido passivo, mantendo o mesmo sujeito.","examples":[{"target":"Having finished the task, she left.","translation_pt_br":"Tendo terminado a tarefa, ela saiu."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Participle clauses.","examples":[{"target":"Built in 1900, the house needs repairs.","translation_pt_br":"Construída em 1900, a casa precisa de reparos."}]}]'::jsonb, '[{"incorrect":"Having finished, the bus arrived.","correct":"Having finished the task, she left.","explanation_pt_br":"A forma incorreta ignora esta regra: Use particípio presente para ações simultâneas/causais e particípio passado para sentido passivo, mantendo o mesmo sujeito."},{"incorrect":"Building in 1900, the house needs repairs.","correct":"Built in 1900, the house needs repairs.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Participle clauses."}]'::jsonb, '["Pratique Participle clauses em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 219),
  ('en-grammar-complete-b2-05', 'en', 'B2', 'Hedging e linguagem acadêmica', 'Use seem, tend to, appear, may, likely e arguably para calibrar certeza e evitar generalizações absolutas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use seem, tend to, appear, may, likely e arguably para calibrar certeza e evitar generalizações absolutas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use seem, tend to, appear, may, likely e arguably para calibrar certeza e evitar generalizações absolutas.","examples":[{"target":"The results appear to support the theory.","translation_pt_br":"Os resultados parecem apoiar a teoria."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Hedging e linguagem acadêmica.","examples":[{"target":"This approach may be more effective.","translation_pt_br":"Esta abordagem pode ser mais eficaz."}]}]'::jsonb, '[{"incorrect":"The results prove absolutely the theory.","correct":"The results appear to support the theory.","explanation_pt_br":"A forma incorreta ignora esta regra: Use seem, tend to, appear, may, likely e arguably para calibrar certeza e evitar generalizações absolutas."},{"incorrect":"This approach is always more effective.","correct":"This approach may be more effective.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Hedging e linguagem acadêmica."}]'::jsonb, '["Pratique Hedging e linguagem acadêmica em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 220),
  ('en-grammar-complete-b2-06', 'en', 'B2', 'Verbos e collocations formais', 'Em registro formal, use combinações como raise concerns, draw a conclusion, address an issue e meet requirements. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Em registro formal, use combinações como raise concerns, draw a conclusion, address an issue e meet requirements. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Em registro formal, use combinações como raise concerns, draw a conclusion, address an issue e meet requirements.","examples":[{"target":"The proposal raises serious concerns.","translation_pt_br":"A proposta levanta preocupações sérias."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Verbos e collocations formais.","examples":[{"target":"We need to address the underlying issue.","translation_pt_br":"Precisamos abordar o problema subjacente."}]}]'::jsonb, '[{"incorrect":"The proposal lifts serious concerns.","correct":"The proposal raises serious concerns.","explanation_pt_br":"A forma incorreta ignora esta regra: Em registro formal, use combinações como raise concerns, draw a conclusion, address an issue e meet requirements."},{"incorrect":"We need to attend the underlying issue.","correct":"We need to address the underlying issue.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Verbos e collocations formais."}]'::jsonb, '["Pratique Verbos e collocations formais em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 221),
  ('es-grammar-complete-a1-01', 'es', 'A1', 'Pronombres personales', 'O espanhol frequentemente omite o pronome sujeito, mas mantém pronomes objeto antes do verbo conjugado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O espanhol frequentemente omite o pronome sujeito, mas mantém pronomes objeto antes do verbo conjugado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O espanhol frequentemente omite o pronome sujeito, mas mantém pronomes objeto antes do verbo conjugado.","examples":[{"target":"Ella me llama cada día.","translation_pt_br":"Ela me liga todos os dias."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronombres personales.","examples":[{"target":"Nosotros los conocemos.","translation_pt_br":"Nós os conhecemos."}]}]'::jsonb, '[{"incorrect":"Ella llama yo cada día.","correct":"Ella me llama cada día.","explanation_pt_br":"A forma incorreta ignora esta regra: O espanhol frequentemente omite o pronome sujeito, mas mantém pronomes objeto antes do verbo conjugado."},{"incorrect":"Nosotros conocemos ellos.","correct":"Nosotros los conocemos.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronombres personales."}]'::jsonb, '["Pratique Pronombres personales em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 222),
  ('es-grammar-complete-a1-02', 'es', 'A1', 'Presente regular', 'Verbos -ar, -er e -ir têm terminações próprias; a pessoa é identificada pela terminação. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Verbos -ar, -er e -ir têm terminações próprias; a pessoa é identificada pela terminação. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Verbos -ar, -er e -ir têm terminações próprias; a pessoa é identificada pela terminação.","examples":[{"target":"Trabajo aquí y vivo cerca.","translation_pt_br":"Trabalho aqui e moro perto."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Presente regular.","examples":[{"target":"¿Comes con nosotros?","translation_pt_br":"Você come conosco?"}]}]'::jsonb, '[{"incorrect":"Yo trabajar aquí y vivir cerca.","correct":"Trabajo aquí y vivo cerca.","explanation_pt_br":"A forma incorreta ignora esta regra: Verbos -ar, -er e -ir têm terminações próprias; a pessoa é identificada pela terminação."},{"incorrect":"¿Tú comer con nosotros?","correct":"¿Comes con nosotros?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Presente regular."}]'::jsonb, '["Pratique Presente regular em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 223),
  ('es-grammar-complete-a1-03', 'es', 'A1', 'Ser, estar e hay', 'Ser identifica e caracteriza; estar localiza e apresenta estado; hay informa existência sem artigo definido. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Ser identifica e caracteriza; estar localiza e apresenta estado; hay informa existência sem artigo definido. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Ser identifica e caracteriza; estar localiza e apresenta estado; hay informa existência sem artigo definido.","examples":[{"target":"Madrid está en España.","translation_pt_br":"Madri fica na Espanha."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Ser, estar e hay.","examples":[{"target":"Hay una farmacia cerca.","translation_pt_br":"Há uma farmácia perto."}]}]'::jsonb, '[{"incorrect":"Madrid es en España.","correct":"Madrid está en España.","explanation_pt_br":"A forma incorreta ignora esta regra: Ser identifica e caracteriza; estar localiza e apresenta estado; hay informa existência sem artigo definido."},{"incorrect":"Está una farmacia cerca.","correct":"Hay una farmacia cerca.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Ser, estar e hay."}]'::jsonb, '["Pratique Ser, estar e hay em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 224),
  ('es-grammar-complete-a1-04', 'es', 'A1', 'Tener e expressões frequentes', 'Use tener para posse, idade, fome, sede, medo, razão e necessidade com tener que. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use tener para posse, idade, fome, sede, medo, razão e necessidade com tener que. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use tener para posse, idade, fome, sede, medo, razão e necessidade com tener que.","examples":[{"target":"Tengo veinte años y tengo hambre.","translation_pt_br":"Tenho vinte anos e estou com fome."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Tener e expressões frequentes.","examples":[{"target":"Tenemos que salir ahora.","translation_pt_br":"Temos que sair agora."}]}]'::jsonb, '[{"incorrect":"Soy veinte años y soy hambre.","correct":"Tengo veinte años y tengo hambre.","explanation_pt_br":"A forma incorreta ignora esta regra: Use tener para posse, idade, fome, sede, medo, razão e necessidade com tener que."},{"incorrect":"Tenemos salir ahora.","correct":"Tenemos que salir ahora.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Tener e expressões frequentes."}]'::jsonb, '["Pratique Tener e expressões frequentes em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 225),
  ('es-grammar-complete-a1-05', 'es', 'A1', 'Ir, venir, hacer e querer', 'Verbos muito frequentes são irregulares e devem ser memorizados em contexto. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Verbos muito frequentes são irregulares e devem ser memorizados em contexto. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Verbos muito frequentes são irregulares e devem ser memorizados em contexto.","examples":[{"target":"Voy al trabajo y hago la comida.","translation_pt_br":"Vou ao trabalho e preparo a comida."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Ir, venir, hacer e querer.","examples":[{"target":"¿Quieres venir conmigo?","translation_pt_br":"Quer vir comigo?"}]}]'::jsonb, '[{"incorrect":"Yo iro al trabajo y haco comida.","correct":"Voy al trabajo y hago la comida.","explanation_pt_br":"A forma incorreta ignora esta regra: Verbos muito frequentes são irregulares e devem ser memorizados em contexto."},{"incorrect":"¿Queres venir con mí?","correct":"¿Quieres venir conmigo?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Ir, venir, hacer e querer."}]'::jsonb, '["Pratique Ir, venir, hacer e querer em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 226),
  ('es-grammar-complete-a1-06', 'es', 'A1', 'Interrogativos e exclamações', 'Qué, cuál, quién, cómo, cuándo, cuánto e dónde recebem acento em perguntas diretas e indiretas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Qué, cuál, quién, cómo, cuándo, cuánto e dónde recebem acento em perguntas diretas e indiretas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Qué, cuál, quién, cómo, cuándo, cuánto e dónde recebem acento em perguntas diretas e indiretas.","examples":[{"target":"¿Dónde vives?","translation_pt_br":"Onde você mora?"}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Interrogativos e exclamações.","examples":[{"target":"No sé qué quiere.","translation_pt_br":"Não sei o que ele quer."}]}]'::jsonb, '[{"incorrect":"¿Donde vives?","correct":"¿Dónde vives?","explanation_pt_br":"A forma incorreta ignora esta regra: Qué, cuál, quién, cómo, cuándo, cuánto e dónde recebem acento em perguntas diretas e indiretas."},{"incorrect":"No sé que quiere.","correct":"No sé qué quiere.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Interrogativos e exclamações."}]'::jsonb, '["Pratique Interrogativos e exclamações em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 227),
  ('es-grammar-complete-a2-01', 'es', 'A2', 'Pretérito perfecto', 'Use haber no presente + particípio para passado ligado ao presente ou período ainda aberto. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use haber no presente + particípio para passado ligado ao presente ou período ainda aberto. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use haber no presente + particípio para passado ligado ao presente ou período ainda aberto.","examples":[{"target":"Hoy he hablado con Ana.","translation_pt_br":"Hoje falei com Ana."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pretérito perfecto.","examples":[{"target":"¿Has visto esta película?","translation_pt_br":"Você já viu este filme?"}]}]'::jsonb, '[{"incorrect":"Hoy soy hablado con Ana.","correct":"Hoy he hablado con Ana.","explanation_pt_br":"A forma incorreta ignora esta regra: Use haber no presente + particípio para passado ligado ao presente ou período ainda aberto."},{"incorrect":"¿Tienes visto esta película?","correct":"¿Has visto esta película?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pretérito perfecto."}]'::jsonb, '["Pratique Pretérito perfecto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 228),
  ('es-grammar-complete-a2-02', 'es', 'A2', 'Pretérito indefinido', 'Use o indefinido para fatos concluídos em período encerrado; verbos frequentes têm formas irregulares. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use o indefinido para fatos concluídos em período encerrado; verbos frequentes têm formas irregulares. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use o indefinido para fatos concluídos em período encerrado; verbos frequentes têm formas irregulares.","examples":[{"target":"Ayer fui al centro y compré un libro.","translation_pt_br":"Ontem fui ao centro e comprei um livro."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pretérito indefinido.","examples":[{"target":"¿Qué hiciste el sábado?","translation_pt_br":"O que você fez no sábado?"}]}]'::jsonb, '[{"incorrect":"Ayer iba al centro y he comprado.","correct":"Ayer fui al centro y compré un libro.","explanation_pt_br":"A forma incorreta ignora esta regra: Use o indefinido para fatos concluídos em período encerrado; verbos frequentes têm formas irregulares."},{"incorrect":"¿Qué haciste el sábado?","correct":"¿Qué hiciste el sábado?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pretérito indefinido."}]'::jsonb, '["Pratique Pretérito indefinido em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 229),
  ('es-grammar-complete-a2-03', 'es', 'A2', 'Pretérito imperfecto', 'Use o imperfeito para hábito, descrição, contexto e ação em progresso no passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use o imperfeito para hábito, descrição, contexto e ação em progresso no passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use o imperfeito para hábito, descrição, contexto e ação em progresso no passado.","examples":[{"target":"Cuando era niño, jugaba aquí.","translation_pt_br":"Quando era criança, brincava aqui."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pretérito imperfecto.","examples":[{"target":"Hacía frío y llovía.","translation_pt_br":"Fazia frio e chovia."}]}]'::jsonb, '[{"incorrect":"Cuando fui niño, jugué aquí siempre.","correct":"Cuando era niño, jugaba aquí.","explanation_pt_br":"A forma incorreta ignora esta regra: Use o imperfeito para hábito, descrição, contexto e ação em progresso no passado."},{"incorrect":"Hizo frío y llovió todo contexto.","correct":"Hacía frío y llovía.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pretérito imperfecto."}]'::jsonb, '["Pratique Pretérito imperfecto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 230),
  ('es-grammar-complete-a2-04', 'es', 'A2', 'Pronombres de objeto', 'Lo/la/los/las substituem objeto direto; le/les substituem indireto e vêm antes do verbo conjugado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Lo/la/los/las substituem objeto direto; le/les substituem indireto e vêm antes do verbo conjugado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Lo/la/los/las substituem objeto direto; le/les substituem indireto e vêm antes do verbo conjugado.","examples":[{"target":"Le doy el libro a Marta.","translation_pt_br":"Dou o livro a Marta."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronombres de objeto.","examples":[{"target":"Quiero comprarlo mañana.","translation_pt_br":"Quero comprá-lo amanhã."}]}]'::jsonb, '[{"incorrect":"La doy el libro a Marta.","correct":"Le doy el libro a Marta.","explanation_pt_br":"A forma incorreta ignora esta regra: Lo/la/los/las substituem objeto direto; le/les substituem indireto e vêm antes do verbo conjugado."},{"incorrect":"Lo quiero comprarlo mañana.","correct":"Quiero comprarlo mañana.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronombres de objeto."}]'::jsonb, '["Pratique Pronombres de objeto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 231),
  ('es-grammar-complete-a2-05', 'es', 'A2', 'Comparativos e superlativos', 'Use más/menos...que, tan...como e el/la más; mejor, peor, mayor e menor são formas especiais. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use más/menos...que, tan...como e el/la más; mejor, peor, mayor e menor são formas especiais. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use más/menos...que, tan...como e el/la más; mejor, peor, mayor e menor são formas especiais.","examples":[{"target":"Este tren es más rápido que aquel.","translation_pt_br":"Este trem é mais rápido que aquele."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Comparativos e superlativos.","examples":[{"target":"Es la mejor opción.","translation_pt_br":"É a melhor opção."}]}]'::jsonb, '[{"incorrect":"Este tren es más rápido de aquel.","correct":"Este tren es más rápido que aquel.","explanation_pt_br":"A forma incorreta ignora esta regra: Use más/menos...que, tan...como e el/la más; mejor, peor, mayor e menor são formas especiais."},{"incorrect":"Es la más buena opción.","correct":"Es la mejor opción.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Comparativos e superlativos."}]'::jsonb, '["Pratique Comparativos e superlativos em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 232),
  ('es-grammar-complete-b1-01', 'es', 'B1', 'Contraste entre passados', 'Indefinido avança eventos concluídos; imperfeito cria contexto, hábito ou ação em curso; perfecto conecta ao presente. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Indefinido avança eventos concluídos; imperfeito cria contexto, hábito ou ação em curso; perfecto conecta ao presente. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Indefinido avança eventos concluídos; imperfeito cria contexto, hábito ou ação em curso; perfecto conecta ao presente.","examples":[{"target":"Mientras trabajaba, sonó el teléfono.","translation_pt_br":"Enquanto trabalhava, o telefone tocou."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Contraste entre passados.","examples":[{"target":"Esta semana he tenido dos reuniones.","translation_pt_br":"Esta semana tive duas reuniões."}]}]'::jsonb, '[{"incorrect":"Mientras trabajé, sonaba el teléfono.","correct":"Mientras trabajaba, sonó el teléfono.","explanation_pt_br":"A forma incorreta ignora esta regra: Indefinido avança eventos concluídos; imperfeito cria contexto, hábito ou ação em curso; perfecto conecta ao presente."},{"incorrect":"Esta semana tuve, aún continúa.","correct":"Esta semana he tenido dos reuniones.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Contraste entre passados."}]'::jsonb, '["Pratique Contraste entre passados em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 233),
  ('es-grammar-complete-b1-02', 'es', 'B1', 'Futuro e condicional', 'O futuro expressa previsão ou suposição; o condicional expressa hipótese, cortesia ou futuro do passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O futuro expressa previsão ou suposição; o condicional expressa hipótese, cortesia ou futuro do passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O futuro expressa previsão ou suposição; o condicional expressa hipótese, cortesia ou futuro do passado.","examples":[{"target":"Mañana tendremos más información.","translation_pt_br":"Amanhã teremos mais informações."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Futuro e condicional.","examples":[{"target":"¿Podrías ayudarme?","translation_pt_br":"Você poderia me ajudar?"}]}]'::jsonb, '[{"incorrect":"Mañana vamos teneremos información.","correct":"Mañana tendremos más información.","explanation_pt_br":"A forma incorreta ignora esta regra: O futuro expressa previsão ou suposição; o condicional expressa hipótese, cortesia ou futuro do passado."},{"incorrect":"¿Pudieras ayudarme ayer futuro?","correct":"¿Podrías ayudarme?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Futuro e condicional."}]'::jsonb, '["Pratique Futuro e condicional em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 234),
  ('es-grammar-complete-b1-03', 'es', 'B1', 'Imperativo afirmativo e negativo', 'O afirmativo tem formas próprias e prende pronomes; o negativo usa no + presente do subjuntivo e pronomes antes. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O afirmativo tem formas próprias e prende pronomes; o negativo usa no + presente do subjuntivo e pronomes antes. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O afirmativo tem formas próprias e prende pronomes; o negativo usa no + presente do subjuntivo e pronomes antes.","examples":[{"target":"Dímelo ahora.","translation_pt_br":"Diga-me isso agora."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Imperativo afirmativo e negativo.","examples":[{"target":"No se lo digas.","translation_pt_br":"Não diga isso a ele."}]}]'::jsonb, '[{"incorrect":"Me di lo ahora.","correct":"Dímelo ahora.","explanation_pt_br":"A forma incorreta ignora esta regra: O afirmativo tem formas próprias e prende pronomes; o negativo usa no + presente do subjuntivo e pronomes antes."},{"incorrect":"No díselo.","correct":"No se lo digas.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Imperativo afirmativo e negativo."}]'::jsonb, '["Pratique Imperativo afirmativo e negativo em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 235),
  ('es-grammar-complete-b1-04', 'es', 'B1', 'Pronombres relativos', 'Que é geral; quien refere-se a pessoas após preposição; cuyo expressa posse e concorda com o nome seguinte. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Que é geral; quien refere-se a pessoas após preposição; cuyo expressa posse e concorda com o nome seguinte. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Que é geral; quien refere-se a pessoas após preposição; cuyo expressa posse e concorda com o nome seguinte.","examples":[{"target":"La persona que llamó dejó un mensaje.","translation_pt_br":"A pessoa que ligou deixou mensagem."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronombres relativos.","examples":[{"target":"Es una autora cuyas obras admiro.","translation_pt_br":"É uma autora cujas obras admiro."}]}]'::jsonb, '[{"incorrect":"La persona quien llamó dejó mensaje.","correct":"La persona que llamó dejó un mensaje.","explanation_pt_br":"A forma incorreta ignora esta regra: Que é geral; quien refere-se a pessoas após preposição; cuyo expressa posse e concorda com o nome seguinte."},{"incorrect":"Es una autora cuyo obras admiro.","correct":"Es una autora cuyas obras admiro.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronombres relativos."}]'::jsonb, '["Pratique Pronombres relativos em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 236),
  ('es-grammar-complete-a1-07', 'es', 'A1', 'Gustar e verbos semelhantes', 'Com gustar, o elemento apreciado controla singular ou plural e a pessoa aparece como objeto indireto. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Com gustar, o elemento apreciado controla singular ou plural e a pessoa aparece como objeto indireto. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Com gustar, o elemento apreciado controla singular ou plural e a pessoa aparece como objeto indireto.","examples":[{"target":"Me gusta esta canción.","translation_pt_br":"Gosto desta música."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Gustar e verbos semelhantes.","examples":[{"target":"Nos gustan los libros.","translation_pt_br":"Gostamos dos livros."}]}]'::jsonb, '[{"incorrect":"Yo gusto esta canción.","correct":"Me gusta esta canción.","explanation_pt_br":"A forma incorreta ignora esta regra: Com gustar, o elemento apreciado controla singular ou plural e a pessoa aparece como objeto indireto."},{"incorrect":"Nos gusta los libros.","correct":"Nos gustan los libros.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Gustar e verbos semelhantes."}]'::jsonb, '["Pratique Gustar e verbos semelhantes em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 237),
  ('es-grammar-complete-b2-01', 'es', 'B2', 'Imperfecto de subjuntivo', 'Use após verbos passados que exigem subjuntivo, hipóteses e construções de cortesia; -ra e -se são possíveis. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use após verbos passados que exigem subjuntivo, hipóteses e construções de cortesia; -ra e -se são possíveis. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use após verbos passados que exigem subjuntivo, hipóteses e construções de cortesia; -ra e -se são possíveis.","examples":[{"target":"Quería que vinieras temprano.","translation_pt_br":"Queria que você viesse cedo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Imperfecto de subjuntivo.","examples":[{"target":"Si tuviera tiempo, viajaría.","translation_pt_br":"Se tivesse tempo, viajaria."}]}]'::jsonb, '[{"incorrect":"Quería que venías temprano.","correct":"Quería que vinieras temprano.","explanation_pt_br":"A forma incorreta ignora esta regra: Use após verbos passados que exigem subjuntivo, hipóteses e construções de cortesia; -ra e -se são possíveis."},{"incorrect":"Si tendría tiempo, viajaría.","correct":"Si tuviera tiempo, viajaría.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Imperfecto de subjuntivo."}]'::jsonb, '["Pratique Imperfecto de subjuntivo em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 238),
  ('es-grammar-complete-b2-02', 'es', 'B2', 'Condicional compuesto', 'Use habría + particípio para resultado não realizado, conjectura passada ou futuro anterior visto do passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use habría + particípio para resultado não realizado, conjectura passada ou futuro anterior visto do passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use habría + particípio para resultado não realizado, conjectura passada ou futuro anterior visto do passado.","examples":[{"target":"Habría aceptado con más información.","translation_pt_br":"Teria aceitado com mais informação."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Condicional compuesto.","examples":[{"target":"Dijo que ya habría terminado.","translation_pt_br":"Disse que já teria terminado."}]}]'::jsonb, '[{"incorrect":"Hubiera aceptar con información.","correct":"Habría aceptado con más información.","explanation_pt_br":"A forma incorreta ignora esta regra: Use habría + particípio para resultado não realizado, conjectura passada ou futuro anterior visto do passado."},{"incorrect":"Dijo que ya terminaría ayer.","correct":"Dijo que ya habría terminado.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Condicional compuesto."}]'::jsonb, '["Pratique Condicional compuesto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 239),
  ('es-grammar-complete-b2-03', 'es', 'B2', 'Pasiva e impessoal avançadas', 'Use ser + particípio para processo, estar + particípio para estado e se para passiva/impessoal natural. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use ser + particípio para processo, estar + particípio para estado e se para passiva/impessoal natural. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use ser + particípio para processo, estar + particípio para estado e se para passiva/impessoal natural.","examples":[{"target":"La propuesta fue aprobada ayer.","translation_pt_br":"A proposta foi aprovada ontem."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pasiva e impessoal avançadas.","examples":[{"target":"Se buscan profesionales con experiencia.","translation_pt_br":"Procuram-se profissionais experientes."}]}]'::jsonb, '[{"incorrect":"La propuesta estuvo aprobada por el comité ayer.","correct":"La propuesta fue aprobada ayer.","explanation_pt_br":"A forma incorreta ignora esta regra: Use ser + particípio para processo, estar + particípio para estado e se para passiva/impessoal natural."},{"incorrect":"Se busca profesionales.","correct":"Se buscan profesionales con experiencia.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pasiva e impessoal avançadas."}]'::jsonb, '["Pratique Pasiva e impessoal avançadas em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 240),
  ('es-grammar-complete-b2-04', 'es', 'B2', 'Verbos de cambio', 'Ponerse, quedarse, volverse, hacerse e llegar a ser expressam tipos diferentes de mudança. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Ponerse, quedarse, volverse, hacerse e llegar a ser expressam tipos diferentes de mudança. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Ponerse, quedarse, volverse, hacerse e llegar a ser expressam tipos diferentes de mudança.","examples":[{"target":"Se puso nervioso al hablar.","translation_pt_br":"Ficou nervoso ao falar."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Verbos de cambio.","examples":[{"target":"Con los años se volvió más paciente.","translation_pt_br":"Com os anos ficou mais paciente."}]}]'::jsonb, '[{"incorrect":"Se hizo nervioso de repente.","correct":"Se puso nervioso al hablar.","explanation_pt_br":"A forma incorreta ignora esta regra: Ponerse, quedarse, volverse, hacerse e llegar a ser expressam tipos diferentes de mudança."},{"incorrect":"Con los años se quedó paciente carácter.","correct":"Con los años se volvió más paciente.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Verbos de cambio."}]'::jsonb, '["Pratique Verbos de cambio em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 241),
  ('es-grammar-complete-b2-05', 'es', 'B2', 'Verbos de opinião e discurso', 'Sostener, plantear, afirmar, señalar, cuestionar e reconocer permitem argumentação precisa e selecionam estruturas próprias. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Sostener, plantear, afirmar, señalar, cuestionar e reconocer permitem argumentação precisa e selecionam estruturas próprias. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Sostener, plantear, afirmar, señalar, cuestionar e reconocer permitem argumentação precisa e selecionam estruturas próprias.","examples":[{"target":"El informe señala que faltan datos.","translation_pt_br":"O relatório aponta que faltam dados."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Verbos de opinião e discurso.","examples":[{"target":"La autora cuestiona la eficacia del método.","translation_pt_br":"A autora questiona a eficácia do método."}]}]'::jsonb, '[{"incorrect":"El informe señala de que faltan datos.","correct":"El informe señala que faltan datos.","explanation_pt_br":"A forma incorreta ignora esta regra: Sostener, plantear, afirmar, señalar, cuestionar e reconocer permitem argumentação precisa e selecionam estruturas próprias."},{"incorrect":"La autora pregunta la eficacia del método.","correct":"La autora cuestiona la eficacia del método.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Verbos de opinião e discurso."}]'::jsonb, '["Pratique Verbos de opinião e discurso em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 242),
  ('es-grammar-complete-b2-06', 'es', 'B2', 'Expressões frequentes e variação regional', 'Vale, qué pena, darse prisa, estar pendiente e tener ganas são frequentes, mas vocabulário cotidiano varia entre países. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Vale, qué pena, darse prisa, estar pendiente e tener ganas são frequentes, mas vocabulário cotidiano varia entre países. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Vale, qué pena, darse prisa, estar pendiente e tener ganas são frequentes, mas vocabulário cotidiano varia entre países.","examples":[{"target":"Tengo ganas de volver pronto.","translation_pt_br":"Estou com vontade de voltar logo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Expressões frequentes e variação regional.","examples":[{"target":"Estate pendiente del correo.","translation_pt_br":"Fique atento ao e-mail."}]}]'::jsonb, '[{"incorrect":"Tengo ganas para volver pronto.","correct":"Tengo ganas de volver pronto.","explanation_pt_br":"A forma incorreta ignora esta regra: Vale, qué pena, darse prisa, estar pendiente e tener ganas são frequentes, mas vocabulário cotidiano varia entre países."},{"incorrect":"Sé pendiente del correo.","correct":"Estate pendiente del correo.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Expressões frequentes e variação regional."}]'::jsonb, '["Pratique Expressões frequentes e variação regional em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 243),
  ('fr-grammar-complete-a1-01', 'fr', 'A1', 'Pronoms sujets et toniques', 'Pronomes sujeito acompanham o verbo; formas tônicas aparecem após preposição, em contraste ou respostas curtas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Pronomes sujeito acompanham o verbo; formas tônicas aparecem após preposição, em contraste ou respostas curtas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Pronomes sujeito acompanham o verbo; formas tônicas aparecem após preposição, em contraste ou respostas curtas.","examples":[{"target":"Elle travaille avec moi.","translation_pt_br":"Ela trabalha comigo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronoms sujets et toniques.","examples":[{"target":"Moi, j''aime le café.","translation_pt_br":"Eu gosto de café."}]}]'::jsonb, '[{"incorrect":"Elle travaille avec je.","correct":"Elle travaille avec moi.","explanation_pt_br":"A forma incorreta ignora esta regra: Pronomes sujeito acompanham o verbo; formas tônicas aparecem após preposição, em contraste ou respostas curtas."},{"incorrect":"Me, je aime le café.","correct":"Moi, j''aime le café.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronoms sujets et toniques."}]'::jsonb, '["Pratique Pronoms sujets et toniques em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 244),
  ('fr-grammar-complete-a1-02', 'fr', 'A1', 'Être, avoir e il y a', 'Être descreve identidade/estado; avoir expressa posse, idade e sensações; il y a indica existência. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Être descreve identidade/estado; avoir expressa posse, idade e sensações; il y a indica existência. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Être descreve identidade/estado; avoir expressa posse, idade e sensações; il y a indica existência.","examples":[{"target":"J''ai vingt ans et j''ai faim.","translation_pt_br":"Tenho vinte anos e estou com fome."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Être, avoir e il y a.","examples":[{"target":"Il y a un café ici.","translation_pt_br":"Há um café aqui."}]}]'::jsonb, '[{"incorrect":"Je suis vingt ans et je suis faim.","correct":"J''ai vingt ans et j''ai faim.","explanation_pt_br":"A forma incorreta ignora esta regra: Être descreve identidade/estado; avoir expressa posse, idade e sensações; il y a indica existência."},{"incorrect":"C''est un café ici existe.","correct":"Il y a un café ici.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Être, avoir e il y a."}]'::jsonb, '["Pratique Être, avoir e il y a em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 245),
  ('fr-grammar-complete-a1-03', 'fr', 'A1', 'Présent des verbes réguliers', 'Verbos em -er, -ir e -re seguem grupos de terminações; o pronome sujeito normalmente é obrigatório. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Verbos em -er, -ir e -re seguem grupos de terminações; o pronome sujeito normalmente é obrigatório. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Verbos em -er, -ir e -re seguem grupos de terminações; o pronome sujeito normalmente é obrigatório.","examples":[{"target":"Nous parlons français.","translation_pt_br":"Falamos francês."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Présent des verbes réguliers.","examples":[{"target":"Ils finissent à six heures.","translation_pt_br":"Eles terminam às seis."}]}]'::jsonb, '[{"incorrect":"Nous parler français.","correct":"Nous parlons français.","explanation_pt_br":"A forma incorreta ignora esta regra: Verbos em -er, -ir e -re seguem grupos de terminações; o pronome sujeito normalmente é obrigatório."},{"incorrect":"Ils finissont à six.","correct":"Ils finissent à six heures.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Présent des verbes réguliers."}]'::jsonb, '["Pratique Présent des verbes réguliers em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 246),
  ('fr-grammar-complete-a1-04', 'fr', 'A1', 'Aller, venir, faire e prendre', 'Esses verbos muito frequentes são irregulares e aparecem em movimento, atividades, clima e refeições. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Esses verbos muito frequentes são irregulares e aparecem em movimento, atividades, clima e refeições. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Esses verbos muito frequentes são irregulares e aparecem em movimento, atividades, clima e refeições.","examples":[{"target":"Je vais au travail et je prends le bus.","translation_pt_br":"Vou ao trabalho e pego o ônibus."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Aller, venir, faire e prendre.","examples":[{"target":"Nous faisons les courses.","translation_pt_br":"Fazemos compras."}]}]'::jsonb, '[{"incorrect":"Je alle au travail et prenne le bus.","correct":"Je vais au travail et je prends le bus.","explanation_pt_br":"A forma incorreta ignora esta regra: Esses verbos muito frequentes são irregulares e aparecem em movimento, atividades, clima e refeições."},{"incorrect":"Nous faisont les courses.","correct":"Nous faisons les courses.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Aller, venir, faire e prendre."}]'::jsonb, '["Pratique Aller, venir, faire e prendre em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 247),
  ('fr-grammar-complete-a1-05', 'fr', 'A1', 'Pouvoir, vouloir e devoir', 'Esses modais são seguidos de infinitivo e expressam capacidade, vontade, pedido ou obrigação. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Esses modais são seguidos de infinitivo e expressam capacidade, vontade, pedido ou obrigação. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Esses modais são seguidos de infinitivo e expressam capacidade, vontade, pedido ou obrigação.","examples":[{"target":"Je peux vous aider.","translation_pt_br":"Posso ajudar você."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pouvoir, vouloir e devoir.","examples":[{"target":"Nous devons partir maintenant.","translation_pt_br":"Precisamos sair agora."}]}]'::jsonb, '[{"incorrect":"Je peux vous aide.","correct":"Je peux vous aider.","explanation_pt_br":"A forma incorreta ignora esta regra: Esses modais são seguidos de infinitivo e expressam capacidade, vontade, pedido ou obrigação."},{"incorrect":"Nous devons partons maintenant.","correct":"Nous devons partir maintenant.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pouvoir, vouloir e devoir."}]'::jsonb, '["Pratique Pouvoir, vouloir e devoir em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 248),
  ('fr-grammar-complete-a1-06', 'fr', 'A1', 'Questions avec est-ce que', 'Use entonação, est-ce que ou inversão; palavras interrogativas vêm no início ou, na fala, no final. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use entonação, est-ce que ou inversão; palavras interrogativas vêm no início ou, na fala, no final. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use entonação, est-ce que ou inversão; palavras interrogativas vêm no início ou, na fala, no final.","examples":[{"target":"Où est-ce que tu habites ?","translation_pt_br":"Onde você mora?"}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Questions avec est-ce que.","examples":[{"target":"Parlez-vous français ?","translation_pt_br":"Você fala francês?"}]}]'::jsonb, '[{"incorrect":"Où que tu habites ?","correct":"Où est-ce que tu habites ?","explanation_pt_br":"A forma incorreta ignora esta regra: Use entonação, est-ce que ou inversão; palavras interrogativas vêm no início ou, na fala, no final."},{"incorrect":"Parlez-tu français ?","correct":"Parlez-vous français ?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Questions avec est-ce que."}]'::jsonb, '["Pratique Questions avec est-ce que em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 249),
  ('fr-grammar-complete-a2-01', 'fr', 'A2', 'Passé composé', 'Forme avoir/être no presente + particípio; com être, o particípio concorda com o sujeito. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Forme avoir/être no presente + particípio; com être, o particípio concorda com o sujeito. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Forme avoir/être no presente + particípio; com être, o particípio concorda com o sujeito.","examples":[{"target":"Elle est arrivée hier.","translation_pt_br":"Ela chegou ontem."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Passé composé.","examples":[{"target":"Nous avons pris le train.","translation_pt_br":"Pegamos o trem."}]}]'::jsonb, '[{"incorrect":"Elle a arrivée hier.","correct":"Elle est arrivée hier.","explanation_pt_br":"A forma incorreta ignora esta regra: Forme avoir/être no presente + particípio; com être, o particípio concorda com o sujeito."},{"incorrect":"Nous sommes prendu le train.","correct":"Nous avons pris le train.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Passé composé."}]'::jsonb, '["Pratique Passé composé em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 250),
  ('fr-grammar-complete-a2-02', 'fr', 'A2', 'Imparfait', 'Use para descrição, hábito, contexto e ação em curso no passado; derive da forma nous do presente. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use para descrição, hábito, contexto e ação em curso no passado; derive da forma nous do presente. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use para descrição, hábito, contexto e ação em curso no passado; derive da forma nous do presente.","examples":[{"target":"Quand j''étais enfant, je jouais ici.","translation_pt_br":"Quando era criança, brincava aqui."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Imparfait.","examples":[{"target":"Il faisait froid.","translation_pt_br":"Fazia frio."}]}]'::jsonb, '[{"incorrect":"Quand j''ai été enfant, j''ai joué toujours ici.","correct":"Quand j''étais enfant, je jouais ici.","explanation_pt_br":"A forma incorreta ignora esta regra: Use para descrição, hábito, contexto e ação em curso no passado; derive da forma nous do presente."},{"incorrect":"Il a fait froid contexte.","correct":"Il faisait froid.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Imparfait."}]'::jsonb, '["Pratique Imparfait em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 251),
  ('fr-grammar-complete-a2-03', 'fr', 'A2', 'Futur proche e futur simple', 'Aller + infinitivo indica futuro próximo/intenção; o futuro simples serve a previsões e registro neutro/formal. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Aller + infinitivo indica futuro próximo/intenção; o futuro simples serve a previsões e registro neutro/formal. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Aller + infinitivo indica futuro próximo/intenção; o futuro simples serve a previsões e registro neutro/formal.","examples":[{"target":"Je vais appeler Marie.","translation_pt_br":"Vou ligar para Marie."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Futur proche e futur simple.","examples":[{"target":"Nous partirons demain.","translation_pt_br":"Partiremos amanhã."}]}]'::jsonb, '[{"incorrect":"Je vais appelle Marie.","correct":"Je vais appeler Marie.","explanation_pt_br":"A forma incorreta ignora esta regra: Aller + infinitivo indica futuro próximo/intenção; o futuro simples serve a previsões e registro neutro/formal."},{"incorrect":"Nous partiront demain.","correct":"Nous partirons demain.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Futur proche e futur simple."}]'::jsonb, '["Pratique Futur proche e futur simple em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 252),
  ('fr-grammar-complete-a2-04', 'fr', 'A2', 'Comparatif e superlatif', 'Use plus/moins/aussi...que e le plus/le moins; bon vira meilleur e bien vira mieux. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use plus/moins/aussi...que e le plus/le moins; bon vira meilleur e bien vira mieux. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use plus/moins/aussi...que e le plus/le moins; bon vira meilleur e bien vira mieux.","examples":[{"target":"Ce livre est meilleur que l''autre.","translation_pt_br":"Este livro é melhor que o outro."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Comparatif e superlatif.","examples":[{"target":"Elle travaille aussi vite que lui.","translation_pt_br":"Ela trabalha tão rápido quanto ele."}]}]'::jsonb, '[{"incorrect":"Ce livre est plus bon que l''autre.","correct":"Ce livre est meilleur que l''autre.","explanation_pt_br":"A forma incorreta ignora esta regra: Use plus/moins/aussi...que e le plus/le moins; bon vira meilleur e bien vira mieux."},{"incorrect":"Elle travaille si vite que lui comparaison.","correct":"Elle travaille aussi vite que lui.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Comparatif e superlatif."}]'::jsonb, '["Pratique Comparatif e superlatif em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 253),
  ('fr-grammar-complete-a2-05', 'fr', 'A2', 'Pronoms objets', 'Me/te/le/la/lui/leur vêm antes do verbo; no passé composé também antecedem o auxiliar. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Me/te/le/la/lui/leur vêm antes do verbo; no passé composé também antecedem o auxiliar. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Me/te/le/la/lui/leur vêm antes do verbo; no passé composé também antecedem o auxiliar.","examples":[{"target":"Je lui donne le document.","translation_pt_br":"Dou o documento a ele."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronoms objets.","examples":[{"target":"Je l''ai vue hier.","translation_pt_br":"Eu a vi ontem."}]}]'::jsonb, '[{"incorrect":"Je le donne le document à lui.","correct":"Je lui donne le document.","explanation_pt_br":"A forma incorreta ignora esta regra: Me/te/le/la/lui/leur vêm antes do verbo; no passé composé também antecedem o auxiliar."},{"incorrect":"J''ai vue la hier.","correct":"Je l''ai vue hier.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronoms objets."}]'::jsonb, '["Pratique Pronoms objets em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 254),
  ('fr-grammar-complete-b1-01', 'fr', 'B1', 'Passé composé ou imparfait', 'O passé composé narra eventos; o imparfait descreve contexto, hábito e ações em curso interrompidas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O passé composé narra eventos; o imparfait descreve contexto, hábito e ações em curso interrompidas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O passé composé narra eventos; o imparfait descreve contexto, hábito e ações em curso interrompidas.","examples":[{"target":"Je lisais quand il a appelé.","translation_pt_br":"Eu lia quando ele ligou."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Passé composé ou imparfait.","examples":[{"target":"Il pleuvait toute la matinée.","translation_pt_br":"Chovia a manhã toda."}]}]'::jsonb, '[{"incorrect":"J''ai lu quand il appelait événement.","correct":"Je lisais quand il a appelé.","explanation_pt_br":"A forma incorreta ignora esta regra: O passé composé narra eventos; o imparfait descreve contexto, hábito e ações em curso interrompidas."},{"incorrect":"Il a plu contexte toute la matinée.","correct":"Il pleuvait toute la matinée.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Passé composé ou imparfait."}]'::jsonb, '["Pratique Passé composé ou imparfait em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 255),
  ('fr-grammar-complete-b1-02', 'fr', 'B1', 'Conditionnel présent', 'Use para hipótese, cortesia, conselho e futuro visto do passado; radical do futuro + terminações do imparfait. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use para hipótese, cortesia, conselho e futuro visto do passado; radical do futuro + terminações do imparfait. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use para hipótese, cortesia, conselho e futuro visto do passado; radical do futuro + terminações do imparfait.","examples":[{"target":"Je voudrais réserver une table.","translation_pt_br":"Gostaria de reservar uma mesa."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Conditionnel présent.","examples":[{"target":"À ta place, je parlerais au directeur.","translation_pt_br":"No seu lugar, falaria com o diretor."}]}]'::jsonb, '[{"incorrect":"Je voudrai réserver politesse.","correct":"Je voudrais réserver une table.","explanation_pt_br":"A forma incorreta ignora esta regra: Use para hipótese, cortesia, conselho e futuro visto do passado; radical do futuro + terminações do imparfait."},{"incorrect":"À ta place, je parlerai au directeur.","correct":"À ta place, je parlerais au directeur.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Conditionnel présent."}]'::jsonb, '["Pratique Conditionnel présent em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 256),
  ('fr-grammar-complete-b1-03', 'fr', 'B1', 'Pronoms relatifs', 'Qui é sujeito, que é objeto, dont substitui de e où refere-se a lugar ou tempo. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Qui é sujeito, que é objeto, dont substitui de e où refere-se a lugar ou tempo. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Qui é sujeito, que é objeto, dont substitui de e où refere-se a lugar ou tempo.","examples":[{"target":"La personne qui parle est ma sœur.","translation_pt_br":"A pessoa que fala é minha irmã."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronoms relatifs.","examples":[{"target":"C''est le livre dont j''ai besoin.","translation_pt_br":"É o livro de que preciso."}]}]'::jsonb, '[{"incorrect":"La personne que parle est ma sœur.","correct":"La personne qui parle est ma sœur.","explanation_pt_br":"A forma incorreta ignora esta regra: Qui é sujeito, que é objeto, dont substitui de e où refere-se a lugar ou tempo."},{"incorrect":"C''est le livre que j''ai besoin.","correct":"C''est le livre dont j''ai besoin.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronoms relatifs."}]'::jsonb, '["Pratique Pronoms relatifs em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 257),
  ('fr-grammar-complete-b1-04', 'fr', 'B1', 'Discours indirect', 'Remova aspas, use que/si/palavra interrogativa e ajuste tempos/referências quando o verbo introdutor está no passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Remova aspas, use que/si/palavra interrogativa e ajuste tempos/referências quando o verbo introdutor está no passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Remova aspas, use que/si/palavra interrogativa e ajuste tempos/referências quando o verbo introdutor está no passado.","examples":[{"target":"Elle a dit qu''elle était prête.","translation_pt_br":"Ela disse que estava pronta."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Discours indirect.","examples":[{"target":"Il m''a demandé si je venais.","translation_pt_br":"Ele perguntou se eu vinha."}]}]'::jsonb, '[{"incorrect":"Elle a dit qu''elle est prête hier.","correct":"Elle a dit qu''elle était prête.","explanation_pt_br":"A forma incorreta ignora esta regra: Remova aspas, use que/si/palavra interrogativa e ajuste tempos/referências quando o verbo introdutor está no passado."},{"incorrect":"Il m''a demandé est-ce que je venais.","correct":"Il m''a demandé si je venais.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Discours indirect."}]'::jsonb, '["Pratique Discours indirect em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 258),
  ('fr-grammar-complete-a1-07', 'fr', 'A1', 'Négation avec ne...pas', 'Coloque ne antes do verbo conjugado e pas depois; diante de vogal, ne vira n''. Na fala informal, ne pode cair. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Coloque ne antes do verbo conjugado e pas depois; diante de vogal, ne vira n''. Na fala informal, ne pode cair. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Coloque ne antes do verbo conjugado e pas depois; diante de vogal, ne vira n''. Na fala informal, ne pode cair.","examples":[{"target":"Je ne travaille pas ici.","translation_pt_br":"Não trabalho aqui."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Négation avec ne...pas.","examples":[{"target":"Elle n''aime pas le café.","translation_pt_br":"Ela não gosta de café."}]}]'::jsonb, '[{"incorrect":"Je travaille ne pas ici.","correct":"Je ne travaille pas ici.","explanation_pt_br":"A forma incorreta ignora esta regra: Coloque ne antes do verbo conjugado e pas depois; diante de vogal, ne vira n''. Na fala informal, ne pode cair."},{"incorrect":"Elle ne pas aime le café.","correct":"Elle n''aime pas le café.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Négation avec ne...pas."}]'::jsonb, '["Pratique Négation avec ne...pas em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 259),
  ('fr-grammar-complete-b2-01', 'fr', 'B2', 'Conditionnel passé', 'Use aurait/serait + particípio para hipótese passada, arrependimento, informação não confirmada ou futuro anterior no passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use aurait/serait + particípio para hipótese passada, arrependimento, informação não confirmada ou futuro anterior no passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use aurait/serait + particípio para hipótese passada, arrependimento, informação não confirmada ou futuro anterior no passado.","examples":[{"target":"J''aurais accepté avec plus de temps.","translation_pt_br":"Teria aceitado com mais tempo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Conditionnel passé.","examples":[{"target":"Il serait parti hier.","translation_pt_br":"Ele teria partido ontem."}]}]'::jsonb, '[{"incorrect":"J''avais accepter avec plus de temps.","correct":"J''aurais accepté avec plus de temps.","explanation_pt_br":"A forma incorreta ignora esta regra: Use aurait/serait + particípio para hipótese passada, arrependimento, informação não confirmada ou futuro anterior no passado."},{"incorrect":"Il aurait parti hier.","correct":"Il serait parti hier.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Conditionnel passé."}]'::jsonb, '["Pratique Conditionnel passé em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 260),
  ('fr-grammar-complete-b2-02', 'fr', 'B2', 'Mise en relief', 'C''est...qui/que e ce qui/ce que destacam constituintes; a estrutura muda conforme função sintática. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: C''est...qui/que e ce qui/ce que destacam constituintes; a estrutura muda conforme função sintática. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"C''est...qui/que e ce qui/ce que destacam constituintes; a estrutura muda conforme função sintática.","examples":[{"target":"C''est Marie qui a appelé.","translation_pt_br":"Foi Marie quem ligou."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Mise en relief.","examples":[{"target":"Ce que je veux, c''est comprendre.","translation_pt_br":"O que quero é entender."}]}]'::jsonb, '[{"incorrect":"C''est Marie que a appelé.","correct":"C''est Marie qui a appelé.","explanation_pt_br":"A forma incorreta ignora esta regra: C''est...qui/que e ce qui/ce que destacam constituintes; a estrutura muda conforme função sintática."},{"incorrect":"Ce qui je veux, c''est comprendre.","correct":"Ce que je veux, c''est comprendre.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Mise en relief."}]'::jsonb, '["Pratique Mise en relief em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 261),
  ('fr-grammar-complete-b2-03', 'fr', 'B2', 'Nominalisation e registro formal', 'Transforme verbos em nomes para condensar informação, escolhendo preposições e artigos adequados. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Transforme verbos em nomes para condensar informação, escolhendo preposições e artigos adequados. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Transforme verbos em nomes para condensar informação, escolhendo preposições e artigos adequados.","examples":[{"target":"La réduction des coûts reste prioritaire.","translation_pt_br":"A redução dos custos continua prioritária."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Nominalisation e registro formal.","examples":[{"target":"La mise en œuvre du projet prendra un an.","translation_pt_br":"A implementação do projeto levará um ano."}]}]'::jsonb, '[{"incorrect":"Le réduire des coûts reste prioritaire.","correct":"La réduction des coûts reste prioritaire.","explanation_pt_br":"A forma incorreta ignora esta regra: Transforme verbos em nomes para condensar informação, escolhendo preposições e artigos adequados."},{"incorrect":"La mettre en œuvre du projet prendra un an.","correct":"La mise en œuvre du projet prendra un an.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Nominalisation e registro formal."}]'::jsonb, '["Pratique Nominalisation e registro formal em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 262),
  ('fr-grammar-complete-b2-04', 'fr', 'B2', 'Concession avancée', 'Bien que e quoique usam subjuntivo; malgré/en dépit de regem nome; avoir beau + infinitivo expressa esforço inútil. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Bien que e quoique usam subjuntivo; malgré/en dépit de regem nome; avoir beau + infinitivo expressa esforço inútil. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Bien que e quoique usam subjuntivo; malgré/en dépit de regem nome; avoir beau + infinitivo expressa esforço inútil.","examples":[{"target":"Bien qu''il soit tard, elle continue.","translation_pt_br":"Embora seja tarde, ela continua."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Concession avancée.","examples":[{"target":"Il a beau essayer, il échoue.","translation_pt_br":"Por mais que tente, fracassa."}]}]'::jsonb, '[{"incorrect":"Bien qu''il est tard, elle continue.","correct":"Bien qu''il soit tard, elle continue.","explanation_pt_br":"A forma incorreta ignora esta regra: Bien que e quoique usam subjuntivo; malgré/en dépit de regem nome; avoir beau + infinitivo expressa esforço inútil."},{"incorrect":"Il est beau essayer, il échoue.","correct":"Il a beau essayer, il échoue.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Concession avancée."}]'::jsonb, '["Pratique Concession avancée em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 263),
  ('fr-grammar-complete-b2-05', 'fr', 'B2', 'Verbes de discours', 'Affirmer, souligner, remettre en cause, constater e reconnaître estruturam argumentos e selecionam complementos específicos. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Affirmer, souligner, remettre en cause, constater e reconnaître estruturam argumentos e selecionam complementos específicos. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Affirmer, souligner, remettre en cause, constater e reconnaître estruturam argumentos e selecionam complementos específicos.","examples":[{"target":"L''étude souligne que les résultats varient.","translation_pt_br":"O estudo destaca que os resultados variam."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Verbes de discours.","examples":[{"target":"L''auteur remet cette idée en cause.","translation_pt_br":"O autor questiona essa ideia."}]}]'::jsonb, '[{"incorrect":"L''étude souligne de que les résultats varient.","correct":"L''étude souligne que les résultats varient.","explanation_pt_br":"A forma incorreta ignora esta regra: Affirmer, souligner, remettre en cause, constater e reconnaître estruturam argumentos e selecionam complementos específicos."},{"incorrect":"L''auteur remet en cause à cette idée.","correct":"L''auteur remet cette idée en cause.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Verbes de discours."}]'::jsonb, '["Pratique Verbes de discours em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 264),
  ('fr-grammar-complete-b2-06', 'fr', 'B2', 'Expressions fréquentes et registre', 'Ça vaut le coup, avoir hâte de, tenir au courant e être censé são frequentes e variam de formalidade. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Ça vaut le coup, avoir hâte de, tenir au courant e être censé são frequentes e variam de formalidade. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Ça vaut le coup, avoir hâte de, tenir au courant e être censé são frequentes e variam de formalidade.","examples":[{"target":"J''ai hâte de vous revoir.","translation_pt_br":"Mal posso esperar para revê-lo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Expressions fréquentes et registre.","examples":[{"target":"Vous êtes censé répondre demain.","translation_pt_br":"Espera-se que você responda amanhã."}]}]'::jsonb, '[{"incorrect":"J''ai hâte pour vous revoir.","correct":"J''ai hâte de vous revoir.","explanation_pt_br":"A forma incorreta ignora esta regra: Ça vaut le coup, avoir hâte de, tenir au courant e être censé são frequentes e variam de formalidade."},{"incorrect":"Vous êtes pensé répondre demain.","correct":"Vous êtes censé répondre demain.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Expressions fréquentes et registre."}]'::jsonb, '["Pratique Expressions fréquentes et registre em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 265),
  ('it-grammar-complete-a1-01', 'it', 'A1', 'Pronomi personali', 'Pronomes sujeito podem ser omitidos; pronomes objeto aparecem antes do verbo ou ligados ao infinitivo. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Pronomes sujeito podem ser omitidos; pronomes objeto aparecem antes do verbo ou ligados ao infinitivo. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Pronomes sujeito podem ser omitidos; pronomes objeto aparecem antes do verbo ou ligados ao infinitivo.","examples":[{"target":"Lei mi chiama ogni giorno.","translation_pt_br":"Ela me liga todos os dias."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronomi personali.","examples":[{"target":"Voglio conoscerli.","translation_pt_br":"Quero conhecê-los."}]}]'::jsonb, '[{"incorrect":"Lei chiama io ogni giorno.","correct":"Lei mi chiama ogni giorno.","explanation_pt_br":"A forma incorreta ignora esta regra: Pronomes sujeito podem ser omitidos; pronomes objeto aparecem antes do verbo ou ligados ao infinitivo."},{"incorrect":"Voglio li conoscere loro.","correct":"Voglio conoscerli.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronomi personali."}]'::jsonb, '["Pratique Pronomi personali em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 266),
  ('it-grammar-complete-a1-02', 'it', 'A1', 'Presente regolare', 'Verbos -are, -ere e -ire seguem terminações próprias; alguns -ire recebem -isc em certas pessoas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Verbos -are, -ere e -ire seguem terminações próprias; alguns -ire recebem -isc em certas pessoas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Verbos -are, -ere e -ire seguem terminações próprias; alguns -ire recebem -isc em certas pessoas.","examples":[{"target":"Parliamo italiano.","translation_pt_br":"Falamos italiano."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Presente regolare.","examples":[{"target":"Finisco il lavoro alle sei.","translation_pt_br":"Termino o trabalho às seis."}]}]'::jsonb, '[{"incorrect":"Noi parlare italiano.","correct":"Parliamo italiano.","explanation_pt_br":"A forma incorreta ignora esta regra: Verbos -are, -ere e -ire seguem terminações próprias; alguns -ire recebem -isc em certas pessoas."},{"incorrect":"Finisco il lavoro a sei ora.","correct":"Finisco il lavoro alle sei.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Presente regolare."}]'::jsonb, '["Pratique Presente regolare em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 267),
  ('it-grammar-complete-a1-03', 'it', 'A1', 'Essere, avere e c''è', 'Essere descreve identidade/estado; avere posse, idade e sensações; c''è/ci sono indicam existência. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Essere descreve identidade/estado; avere posse, idade e sensações; c''è/ci sono indicam existência. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Essere descreve identidade/estado; avere posse, idade e sensações; c''è/ci sono indicam existência.","examples":[{"target":"Ho vent''anni e ho fame.","translation_pt_br":"Tenho vinte anos e estou com fome."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Essere, avere e c''è.","examples":[{"target":"Ci sono due bar qui.","translation_pt_br":"Há dois bares aqui."}]}]'::jsonb, '[{"incorrect":"Sono vent''anni e sono fame.","correct":"Ho vent''anni e ho fame.","explanation_pt_br":"A forma incorreta ignora esta regra: Essere descreve identidade/estado; avere posse, idade e sensações; c''è/ci sono indicam existência."},{"incorrect":"C''è due bar qui.","correct":"Ci sono due bar qui.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Essere, avere e c''è."}]'::jsonb, '["Pratique Essere, avere e c''è em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 268),
  ('it-grammar-complete-a1-04', 'it', 'A1', 'Andare, venire, fare e stare', 'Verbos frequentes são irregulares e aparecem em movimento, atividades, clima, saúde e cumprimentos. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Verbos frequentes são irregulares e aparecem em movimento, atividades, clima, saúde e cumprimentos. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Verbos frequentes são irregulares e aparecem em movimento, atividades, clima, saúde e cumprimentos.","examples":[{"target":"Vado al lavoro e faccio colazione.","translation_pt_br":"Vou ao trabalho e tomo café da manhã."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Andare, venire, fare e stare.","examples":[{"target":"Come stai oggi?","translation_pt_br":"Como você está hoje?"}]}]'::jsonb, '[{"incorrect":"Ando al lavoro e faccio la colazione.","correct":"Vado al lavoro e faccio colazione.","explanation_pt_br":"A forma incorreta ignora esta regra: Verbos frequentes são irregulares e aparecem em movimento, atividades, clima, saúde e cumprimentos."},{"incorrect":"Come sei oggi salute?","correct":"Come stai oggi?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Andare, venire, fare e stare."}]'::jsonb, '["Pratique Andare, venire, fare e stare em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 269),
  ('it-grammar-complete-a1-05', 'it', 'A1', 'Potere, volere e dovere', 'Esses modais são seguidos diretamente de infinitivo e compartilham o auxiliar do verbo principal nos tempos compostos. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Esses modais são seguidos diretamente de infinitivo e compartilham o auxiliar do verbo principal nos tempos compostos. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Esses modais são seguidos diretamente de infinitivo e compartilham o auxiliar do verbo principal nos tempos compostos.","examples":[{"target":"Posso aiutarti.","translation_pt_br":"Posso ajudar você."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Potere, volere e dovere.","examples":[{"target":"Dobbiamo partire adesso.","translation_pt_br":"Precisamos sair agora."}]}]'::jsonb, '[{"incorrect":"Posso ti aiuto.","correct":"Posso aiutarti.","explanation_pt_br":"A forma incorreta ignora esta regra: Esses modais são seguidos diretamente de infinitivo e compartilham o auxiliar do verbo principal nos tempos compostos."},{"incorrect":"Dobbiamo partiamo adesso.","correct":"Dobbiamo partire adesso.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Potere, volere e dovere."}]'::jsonb, '["Pratique Potere, volere e dovere em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 270),
  ('it-grammar-complete-a1-06', 'it', 'A1', 'Interrogativi', 'Chi, che/cosa, quale, come, dove, quando, perché e quanto introduzem perguntas sem inversão obrigatória. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Chi, che/cosa, quale, come, dove, quando, perché e quanto introduzem perguntas sem inversão obrigatória. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Chi, che/cosa, quale, come, dove, quando, perché e quanto introduzem perguntas sem inversão obrigatória.","examples":[{"target":"Dove abiti?","translation_pt_br":"Onde você mora?"}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Interrogativi.","examples":[{"target":"Quale preferisci?","translation_pt_br":"Qual você prefere?"}]}]'::jsonb, '[{"incorrect":"Dove tu abiti è?","correct":"Dove abiti?","explanation_pt_br":"A forma incorreta ignora esta regra: Chi, che/cosa, quale, come, dove, quando, perché e quanto introduzem perguntas sem inversão obrigatória."},{"incorrect":"Che preferisci quale?","correct":"Quale preferisci?","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Interrogativi."}]'::jsonb, '["Pratique Interrogativi em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 271),
  ('it-grammar-complete-a2-01', 'it', 'A2', 'Passato prossimo', 'Forme avere/essere no presente + particípio; com essere, concorde gênero e número. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Forme avere/essere no presente + particípio; com essere, concorde gênero e número. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Forme avere/essere no presente + particípio; com essere, concorde gênero e número.","examples":[{"target":"Maria è arrivata ieri.","translation_pt_br":"Maria chegou ontem."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Passato prossimo.","examples":[{"target":"Abbiamo preso il treno.","translation_pt_br":"Pegamos o trem."}]}]'::jsonb, '[{"incorrect":"Maria ha arrivato ieri.","correct":"Maria è arrivata ieri.","explanation_pt_br":"A forma incorreta ignora esta regra: Forme avere/essere no presente + particípio; com essere, concorde gênero e número."},{"incorrect":"Siamo prenduto il treno.","correct":"Abbiamo preso il treno.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Passato prossimo."}]'::jsonb, '["Pratique Passato prossimo em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 272),
  ('it-grammar-complete-a2-02', 'it', 'A2', 'Imperfetto', 'Use para descrição, hábito, idade, contexto e ação em curso no passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use para descrição, hábito, idade, contexto e ação em curso no passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use para descrição, hábito, idade, contexto e ação em curso no passado.","examples":[{"target":"Da bambino giocavo qui.","translation_pt_br":"Quando criança, brincava aqui."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Imperfetto.","examples":[{"target":"Faceva freddo e pioveva.","translation_pt_br":"Fazia frio e chovia."}]}]'::jsonb, '[{"incorrect":"Da bambino ho giocato sempre qui.","correct":"Da bambino giocavo qui.","explanation_pt_br":"A forma incorreta ignora esta regra: Use para descrição, hábito, idade, contexto e ação em curso no passado."},{"incorrect":"Ha fatto freddo contesto e ha piovuto.","correct":"Faceva freddo e pioveva.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Imperfetto."}]'::jsonb, '["Pratique Imperfetto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 273),
  ('it-grammar-complete-a2-03', 'it', 'A2', 'Futuro semplice', 'Use para eventos futuros e também suposição sobre o presente; vários radicais são irregulares. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use para eventos futuros e também suposição sobre o presente; vários radicais são irregulares. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use para eventos futuros e também suposição sobre o presente; vários radicais são irregulares.","examples":[{"target":"Domani partiremo presto.","translation_pt_br":"Amanhã partiremos cedo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Futuro semplice.","examples":[{"target":"Saranno le otto.","translation_pt_br":"Devem ser oito horas."}]}]'::jsonb, '[{"incorrect":"Domani partiremmo presto.","correct":"Domani partiremo presto.","explanation_pt_br":"A forma incorreta ignora esta regra: Use para eventos futuros e também suposição sobre o presente; vários radicais são irregulares."},{"incorrect":"Sono le otto futuro.","correct":"Saranno le otto.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Futuro semplice."}]'::jsonb, '["Pratique Futuro semplice em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 274),
  ('it-grammar-complete-a2-04', 'it', 'A2', 'Comparativi e superlativi', 'Use più/meno...di ou che, tanto...quanto e il più; buono/migliore e bene/meglio exigem distinção. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use più/meno...di ou che, tanto...quanto e il più; buono/migliore e bene/meglio exigem distinção. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use più/meno...di ou che, tanto...quanto e il più; buono/migliore e bene/meglio exigem distinção.","examples":[{"target":"Questo libro è migliore dell''altro.","translation_pt_br":"Este livro é melhor que o outro."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Comparativi e superlativi.","examples":[{"target":"Lavora tanto quanto me.","translation_pt_br":"Trabalha tanto quanto eu."}]}]'::jsonb, '[{"incorrect":"Questo libro è più buono dell''altro.","correct":"Questo libro è migliore dell''altro.","explanation_pt_br":"A forma incorreta ignora esta regra: Use più/meno...di ou che, tanto...quanto e il più; buono/migliore e bene/meglio exigem distinção."},{"incorrect":"Lavora così quanto io.","correct":"Lavora tanto quanto me.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Comparativi e superlativi."}]'::jsonb, '["Pratique Comparativi e superlativi em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 275),
  ('it-grammar-complete-a2-05', 'it', 'A2', 'Pronomi diretti e indiretti', 'Lo/la/li/le são diretos; gli/le é indireto singular; pronomes vêm antes do verbo e podem ligar-se ao infinitivo. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Lo/la/li/le são diretos; gli/le é indireto singular; pronomes vêm antes do verbo e podem ligar-se ao infinitivo. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Lo/la/li/le são diretos; gli/le é indireto singular; pronomes vêm antes do verbo e podem ligar-se ao infinitivo.","examples":[{"target":"Le do il documento.","translation_pt_br":"Dou o documento a ela."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronomi diretti e indiretti.","examples":[{"target":"Voglio comprarlo domani.","translation_pt_br":"Quero comprá-lo amanhã."}]}]'::jsonb, '[{"incorrect":"La do il documento.","correct":"Le do il documento.","explanation_pt_br":"A forma incorreta ignora esta regra: Lo/la/li/le são diretos; gli/le é indireto singular; pronomes vêm antes do verbo e podem ligar-se ao infinitivo."},{"incorrect":"Lo voglio comprarlo domani.","correct":"Voglio comprarlo domani.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronomi diretti e indiretti."}]'::jsonb, '["Pratique Pronomi diretti e indiretti em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 276),
  ('it-grammar-complete-b1-01', 'it', 'B1', 'Passato prossimo ou imperfetto', 'O passato prossimo avança eventos concluídos; o imperfetto cria contexto, hábito e ação em curso. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O passato prossimo avança eventos concluídos; o imperfetto cria contexto, hábito e ação em curso. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O passato prossimo avança eventos concluídos; o imperfetto cria contexto, hábito e ação em curso.","examples":[{"target":"Leggevo quando ha telefonato.","translation_pt_br":"Eu lia quando ele ligou."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Passato prossimo ou imperfetto.","examples":[{"target":"Questa settimana ho avuto due riunioni.","translation_pt_br":"Esta semana tive duas reuniões."}]}]'::jsonb, '[{"incorrect":"Ho letto quando telefonava evento.","correct":"Leggevo quando ha telefonato.","explanation_pt_br":"A forma incorreta ignora esta regra: O passato prossimo avança eventos concluídos; o imperfetto cria contexto, hábito e ação em curso."},{"incorrect":"Questa settimana avevo due riunioni concluse.","correct":"Questa settimana ho avuto due riunioni.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Passato prossimo ou imperfetto."}]'::jsonb, '["Pratique Passato prossimo ou imperfetto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 277),
  ('it-grammar-complete-b1-02', 'it', 'B1', 'Condizionale presente', 'Use para hipótese, cortesia, conselho e futuro do passado; o radical é próximo ao futuro. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use para hipótese, cortesia, conselho e futuro do passado; o radical é próximo ao futuro. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use para hipótese, cortesia, conselho e futuro do passado; o radical é próximo ao futuro.","examples":[{"target":"Vorrei prenotare una camera.","translation_pt_br":"Gostaria de reservar um quarto."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Condizionale presente.","examples":[{"target":"Al tuo posto, parlerei con lei.","translation_pt_br":"No seu lugar, falaria com ela."}]}]'::jsonb, '[{"incorrect":"Vorrò prenotare cortesia.","correct":"Vorrei prenotare una camera.","explanation_pt_br":"A forma incorreta ignora esta regra: Use para hipótese, cortesia, conselho e futuro do passado; o radical é próximo ao futuro."},{"incorrect":"Al tuo posto, parlerò con lei.","correct":"Al tuo posto, parlerei con lei.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Condizionale presente."}]'::jsonb, '["Pratique Condizionale presente em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 278),
  ('it-grammar-complete-b1-03', 'it', 'B1', 'Pronomi relativi', 'Che é sujeito/objeto sem preposição; cui vem após preposição; il quale varia e pode esclarecer referência. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Che é sujeito/objeto sem preposição; cui vem após preposição; il quale varia e pode esclarecer referência. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Che é sujeito/objeto sem preposição; cui vem após preposição; il quale varia e pode esclarecer referência.","examples":[{"target":"La persona che parla è mia sorella.","translation_pt_br":"A pessoa que fala é minha irmã."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Pronomi relativi.","examples":[{"target":"Il collega con cui lavoro è nuovo.","translation_pt_br":"O colega com quem trabalho é novo."}]}]'::jsonb, '[{"incorrect":"La persona cui parla è mia sorella.","correct":"La persona che parla è mia sorella.","explanation_pt_br":"A forma incorreta ignora esta regra: Che é sujeito/objeto sem preposição; cui vem após preposição; il quale varia e pode esclarecer referência."},{"incorrect":"Il collega che lavoro è nuovo.","correct":"Il collega con cui lavoro è nuovo.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Pronomi relativi."}]'::jsonb, '["Pratique Pronomi relativi em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 279),
  ('it-grammar-complete-b1-04', 'it', 'B1', 'Discorso indiretto', 'Use che/se/palavra interrogativa e ajuste pessoas, tempos e referências conforme o ponto de vista narrativo. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use che/se/palavra interrogativa e ajuste pessoas, tempos e referências conforme o ponto de vista narrativo. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use che/se/palavra interrogativa e ajuste pessoas, tempos e referências conforme o ponto de vista narrativo.","examples":[{"target":"Ha detto che era stanca.","translation_pt_br":"Disse que estava cansada."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Discorso indiretto.","examples":[{"target":"Mi ha chiesto dove abitavo.","translation_pt_br":"Perguntou onde eu morava."}]}]'::jsonb, '[{"incorrect":"Ha detto che sono stanca ieri.","correct":"Ha detto che era stanca.","explanation_pt_br":"A forma incorreta ignora esta regra: Use che/se/palavra interrogativa e ajuste pessoas, tempos e referências conforme o ponto de vista narrativo."},{"incorrect":"Mi ha chiesto dove abitavo? inversione.","correct":"Mi ha chiesto dove abitavo.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Discorso indiretto."}]'::jsonb, '["Pratique Discorso indiretto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 280),
  ('it-grammar-complete-a1-07', 'it', 'A1', 'Articoli determinativi e indeterminativi', 'Escolha il/lo/la/i/gli/le conforme gênero, número e som inicial; un/uno/una seguem o mesmo princípio. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Escolha il/lo/la/i/gli/le conforme gênero, número e som inicial; un/uno/una seguem o mesmo princípio. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Escolha il/lo/la/i/gli/le conforme gênero, número e som inicial; un/uno/una seguem o mesmo princípio.","examples":[{"target":"Lo studente legge il libro.","translation_pt_br":"O estudante lê o livro."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Articoli determinativi e indeterminativi.","examples":[{"target":"Ho uno zaino e un''amica italiana.","translation_pt_br":"Tenho uma mochila e uma amiga italiana."}]}]'::jsonb, '[{"incorrect":"Il studente legge lo libro.","correct":"Lo studente legge il libro.","explanation_pt_br":"A forma incorreta ignora esta regra: Escolha il/lo/la/i/gli/le conforme gênero, número e som inicial; un/uno/una seguem o mesmo princípio."},{"incorrect":"Ho un zaino e una amica italiana.","correct":"Ho uno zaino e un''amica italiana.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Articoli determinativi e indeterminativi."}]'::jsonb, '["Pratique Articoli determinativi e indeterminativi em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 281),
  ('it-grammar-complete-b2-01', 'it', 'B2', 'Condizionale passato', 'Use avere/essere no condicional + particípio para hipótese passada, arrependimento ou futuro anterior no passado. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Use avere/essere no condicional + particípio para hipótese passada, arrependimento ou futuro anterior no passado. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Use avere/essere no condicional + particípio para hipótese passada, arrependimento ou futuro anterior no passado.","examples":[{"target":"Avrei accettato con più tempo.","translation_pt_br":"Teria aceitado com mais tempo."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Condizionale passato.","examples":[{"target":"Sarebbero partiti prima.","translation_pt_br":"Teriam partido antes."}]}]'::jsonb, '[{"incorrect":"Avevo accettare con più tempo.","correct":"Avrei accettato con più tempo.","explanation_pt_br":"A forma incorreta ignora esta regra: Use avere/essere no condicional + particípio para hipótese passada, arrependimento ou futuro anterior no passado."},{"incorrect":"Avrebbero partito prima.","correct":"Sarebbero partiti prima.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Condizionale passato."}]'::jsonb, '["Pratique Condizionale passato em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 282),
  ('it-grammar-complete-b2-02', 'it', 'B2', 'Periodo ipotetico misto', 'Combine trapassato do subjuntivo e condicional presente quando uma condição passada produz efeito atual. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Combine trapassato do subjuntivo e condicional presente quando uma condição passada produz efeito atual. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Combine trapassato do subjuntivo e condicional presente quando uma condição passada produz efeito atual.","examples":[{"target":"Se avessi studiato medicina, ora sarei medico.","translation_pt_br":"Se tivesse estudado medicina, hoje seria médico."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Periodo ipotetico misto.","examples":[{"target":"Se fossi più attento, non avresti sbagliato.","translation_pt_br":"Se fosse mais atento, não teria errado."}]}]'::jsonb, '[{"incorrect":"Se avrei studiato, ora ero medico.","correct":"Se avessi studiato medicina, ora sarei medico.","explanation_pt_br":"A forma incorreta ignora esta regra: Combine trapassato do subjuntivo e condicional presente quando uma condição passada produz efeito atual."},{"incorrect":"Se saresti attento, non sbagliavi.","correct":"Se fossi più attento, non avresti sbagliato.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Periodo ipotetico misto."}]'::jsonb, '["Pratique Periodo ipotetico misto em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 283),
  ('it-grammar-complete-b2-03', 'it', 'B2', 'Dislocazione e pronomi de retomada', 'Na fala e escrita marcada, um constituinte pode ser deslocado e retomado por pronome para organizar tópico e foco. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Na fala e escrita marcada, um constituinte pode ser deslocado e retomado por pronome para organizar tópico e foco. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Na fala e escrita marcada, um constituinte pode ser deslocado e retomado por pronome para organizar tópico e foco.","examples":[{"target":"Quel libro, l''ho già letto.","translation_pt_br":"Aquele livro, já o li."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Dislocazione e pronomi de retomada.","examples":[{"target":"A Maria, le ho scritto ieri.","translation_pt_br":"Para Maria, escrevi ontem."}]}]'::jsonb, '[{"incorrect":"Quel libro, ho già letto lui.","correct":"Quel libro, l''ho già letto.","explanation_pt_br":"A forma incorreta ignora esta regra: Na fala e escrita marcada, um constituinte pode ser deslocado e retomado por pronome para organizar tópico e foco."},{"incorrect":"A Maria, ho scritto lei ieri.","correct":"A Maria, le ho scritto ieri.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Dislocazione e pronomi de retomada."}]'::jsonb, '["Pratique Dislocazione e pronomi de retomada em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 284),
  ('it-grammar-complete-b2-04', 'it', 'B2', 'Gerundio e participio', 'O gerúndio expressa simultaneidade, modo ou causa com mesmo sujeito; particípios podem condensar orações passivas. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: O gerúndio expressa simultaneidade, modo ou causa com mesmo sujeito; particípios podem condensar orações passivas. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"O gerúndio expressa simultaneidade, modo ou causa com mesmo sujeito; particípios podem condensar orações passivas.","examples":[{"target":"Avendo finito il lavoro, uscì.","translation_pt_br":"Tendo terminado o trabalho, saiu."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Gerundio e participio.","examples":[{"target":"Costruita nel 1900, la casa è storica.","translation_pt_br":"Construída em 1900, a casa é histórica."}]}]'::jsonb, '[{"incorrect":"Avendo finito, il telefono suonò.","correct":"Avendo finito il lavoro, uscì.","explanation_pt_br":"A forma incorreta ignora esta regra: O gerúndio expressa simultaneidade, modo ou causa com mesmo sujeito; particípios podem condensar orações passivas."},{"incorrect":"Costruendo nel 1900, la casa è storica.","correct":"Costruita nel 1900, la casa è storica.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Gerundio e participio."}]'::jsonb, '["Pratique Gerundio e participio em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 285),
  ('it-grammar-complete-b2-05', 'it', 'B2', 'Verbi di discorso', 'Affermare, sottolineare, sostenere, mettere in dubbio e riconoscere dão precisão argumentativa e exigem complementos adequados. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Affermare, sottolineare, sostenere, mettere in dubbio e riconoscere dão precisão argumentativa e exigem complementos adequados. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Affermare, sottolineare, sostenere, mettere in dubbio e riconoscere dão precisão argumentativa e exigem complementos adequados.","examples":[{"target":"Lo studio sottolinea che i dati variano.","translation_pt_br":"O estudo destaca que os dados variam."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Verbi di discorso.","examples":[{"target":"L''autore mette in dubbio questa teoria.","translation_pt_br":"O autor põe esta teoria em dúvida."}]}]'::jsonb, '[{"incorrect":"Lo studio sottolinea di che i dati variano.","correct":"Lo studio sottolinea che i dati variano.","explanation_pt_br":"A forma incorreta ignora esta regra: Affermare, sottolineare, sostenere, mettere in dubbio e riconoscere dão precisão argumentativa e exigem complementos adequados."},{"incorrect":"L''autore mette questa teoria al dubbio.","correct":"L''autore mette in dubbio questa teoria.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Verbi di discorso."}]'::jsonb, '["Pratique Verbi di discorso em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 286),
  ('it-grammar-complete-b2-06', 'it', 'B2', 'Espressioni frequenti e registro', 'Non vedere l''ora, valere la pena, tenere aggiornato, essere in grado e avere a che fare são blocos frequentes. Este tema reúne os usos mais frequentes na comunicação cotidiana e mostra como evitar interferências diretas do português.', 'Regra central: Non vedere l''ora, valere la pena, tenere aggiornato, essere in grado e avere a che fare são blocos frequentes. Analise a função do verbo ou da expressão antes de escolher a forma e confirme a regência no contexto completo.', '[{"title_pt_br":"Uso principal","explanation_pt_br":"Non vedere l''ora, valere la pena, tenere aggiornato, essere in grado e avere a che fare são blocos frequentes.","examples":[{"target":"Non vedo l''ora di partire.","translation_pt_br":"Mal posso esperar para partir."}]},{"title_pt_br":"Uso em contexto","explanation_pt_br":"A mesma regra aparece em perguntas, negações, relatos ou situações de uso natural relacionadas a Espressioni frequenti e registro.","examples":[{"target":"Questo problema ha a che fare con i costi.","translation_pt_br":"Este problema tem relação com os custos."}]}]'::jsonb, '[{"incorrect":"Non vedo l''ora per partire.","correct":"Non vedo l''ora di partire.","explanation_pt_br":"A forma incorreta ignora esta regra: Non vedere l''ora, valere la pena, tenere aggiornato, essere in grado e avere a che fare são blocos frequentes."},{"incorrect":"Questo problema ha da fare ai costi.","correct":"Questo problema ha a che fare con i costi.","explanation_pt_br":"A construção deve preservar a forma e a regência apresentadas no tema Espressioni frequenti e registro."}]'::jsonb, '["Pratique Espressioni frequenti e registro em frases completas.","Compare sempre a forma correta com o erro típico de falantes de português."]'::jsonb, 287);

-- Completa cinco exercícios para cada tema, preservando os exercícios existentes.
insert into public.grammar_exercises (
  id, topic_id, language, level, title, explanation, example,
  question, options, answer_index, sort_order, is_published
)
select
  topic.id || '-practice-' || slot.number,
  topic.id, topic.language, topic.level,
  left(topic.title || ' · prática ' || slot.number, 160),
  mistake.value ->> 'explanation_pt_br',
  mistake.value ->> 'correct',
  case topic.language
    when 'en' then 'Choose the correct sentence.'
    when 'es' then 'Elige la frase correcta.'
    when 'fr' then 'Choisissez la phrase correcte.'
    else 'Scegli la frase corretta.'
  end,
  jsonb_build_array(
    mistake.value ->> 'incorrect',
    mistake.value ->> 'correct',
    topic.common_mistakes -> (slot.number % jsonb_array_length(topic.common_mistakes)) ->> 'incorrect'
  ),
  1,
  topic.sort_order * 10 + slot.number,
  true
from public.grammar_topics topic
cross join lateral (
  select count(*)::integer as existing_count
  from public.grammar_exercises existing
  where existing.topic_id = topic.id and existing.is_published
) count_data
cross join lateral generate_series(count_data.existing_count + 1, 5) as slot(number)
cross join lateral jsonb_array_elements(topic.common_mistakes) with ordinality as mistake(value, position)
where topic.is_published
  and mistake.position = ((slot.number - 1) % jsonb_array_length(topic.common_mistakes)) + 1;
